package com.wiffeyyyy.hotline;
import android.app.Activity;import android.app.NotificationManager;import android.content.Intent;import android.os.Bundle;import android.widget.*;
public class IncomingActivity extends Activity {
 volatile boolean alive=true;Thread monitor;
 @Override public void onCreate(Bundle state){super.onCreate(state);if(android.os.Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|android.view.WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);String id=getIntent().getStringExtra("callId");LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setGravity(17);layout.setPadding(30,40,30,40);layout.setBackgroundColor(0xfffff5f7);TextView title=new TextView(this);title.setText("Incoming Hotline call ♡");title.setTextSize(26);layout.addView(title);Button answer=new Button(this);answer.setText("Answer");answer.setOnClickListener(v->{getSystemService(NotificationManager.class).cancel(HotlineService.INCOMING);startActivity(new Intent(this,MainActivity.class).putExtra("answer",true).putExtra("callId",id));finish();});layout.addView(answer);Button decline=new Button(this);decline.setText("Decline");decline.setOnClickListener(v->{startService(new Intent(this,HotlineService.class).setAction(HotlineService.DECLINE).putExtra("callId",id));finish();});layout.addView(decline);setContentView(layout);monitor=new Thread(()->{while(alive){try{org.json.JSONObject call=Config.exchange(this,"status",new org.json.JSONObject());if(!id.equals(call.optString("callId"))||!"ringing".equals(call.optString("state"))){runOnUiThread(this::finish);return;}Thread.sleep(1200);}catch(InterruptedException e){return;}catch(Exception e){try{Thread.sleep(2000);}catch(InterruptedException stop){return;}}}});monitor.start();}
 @Override public void onDestroy(){alive=false;if(monitor!=null)monitor.interrupt();super.onDestroy();}
}
